import type { ReactNode } from 'react'
/** Renders **bold** inside plain text (all coach text is generated by us, so no HTML is ever injected). */
export function Md({ text }: { text: string }) {
  const parts: ReactNode[] = []
  text.split(/(\*\*[^*]+\*\*)/g).forEach((s, i) => {
    if (s.startsWith('**') && s.endsWith('**')) parts.push(<b key={i}>{s.slice(2, -2)}</b>)
    else if (s) parts.push(s)
  })
  return <>{parts}</>
}
